const main=document.querySelector('main');
const nav=[['','⌂','Home'],['writing','▤','Writing'],['play','♧','Play'],['guestbook','☏','Guestbook'],['about','☺','About']];
const posts=[['Notes on moving from security to revenue operations','Work notes'],['Learning to explain technical things','Learning'],['Building a small place on the internet','Site notes']];
const steps=['Body','Draw','Movement','Personality','Release'];
const panel=(title,body,color='blue')=>`<section class="panel"><h2 class="panelhead ${color}">${title}</h2><div class="panelbody">${body}</div></section>`;
const btn=(text,href,primary=false)=>`<a class="button ${primary?'primary':''}" href="#/${href}">${text}</a>`;
const note='<p class="preview-note">Layout preview · example content and static artwork. The game is not connected yet.</p>';
const rows=()=>posts.map((p,i)=>`<div class="writingrow" data-category="${p[1]}"><span class="muted">Sample / 0${i+1}</span><div><a href="#/writing/${i}">${p[0]}</a><p class="small-copy muted">${p[1]}</p></div></div>`).join('');
const hill=()=>`<div class="hill"><img src="assets/footer.png" alt="Five creatures hanging out beside a bench and mushroom house"><a class="hilllink" href="#/village">Visit the village →</a></div>`;
const playcards=()=>`<div class="playcards"><a class="playcard" href="#/maker/body"><div class="thumb"><img class="goblin" src="assets/goblin.png" alt="Green goblin"></div><h3>Make a creature</h3><p>Draw someone. Give them a life here.</p></a><a class="playcard" href="#/village"><div class="thumb mapthumb"><img src="assets/village.png" alt="Mushroom village"></div><h3>The village</h3><p>A small window into a bigger place.</p></a></div>`;
function home(){return `<div class="homegrid"><div class="stack">${panel('Recent writing',rows()+'<a class="morelink" href="#/writing">All writing →</a>')}${panel('A place to play',playcards(),'green')}</div><aside class="stack">${panel('Currently','<ul class="currently"><li>Working in revenue operations</li><li>Learning towards sales engineering</li><li>Building this website</li></ul>','green')}${panel('About','<p>I’m Vishnu. My background is in DevOps and cybersecurity; these days I’m working in revenue operations.</p><a href="#/about">More about me →</a>','yellow')}${panel('Guestbook','<p>A space for visitors to leave a note.</p><p class="sample">The book is empty for now.</p><a href="#/guestbook">Open the guestbook →</a>')}</aside></div>${hill()}`}
function writing(id){if(id!==undefined){const p=posts[Number(id)];if(!p)return writing();return `<article class="article panel"><div class="panelbody"><a href="#/writing">← Back to writing</a><p class="sample">Sample article layout · not a published post</p><h1>${p[0]}</h1><p>This is where the full essay will live. The reading page keeps the illustrations at the edges and gives the text room to breathe.</p><h2>A little space to think</h2><p>Longer paragraphs, links, code samples and images can sit here. The actual writing will replace this sample before launch.</p><blockquote>A useful observation, with enough room around it.</blockquote><p>There’s no need to invent a body of work to fill the page. A few honest notes are a good starting point.</p></div></article>`}return `<div class="pageheading"><h1>Writing</h1><p>Work notes, things I’m learning, and occasional longer thoughts.</p></div>${panel('Notebook',`<p class="sample">Example titles to review the layout. These are not published articles.</p><div class="filterbar">${['All','Work notes','Learning','Site notes'].map((x,i)=>`<button class="${i?'':'active'}" data-filter="${x}">${x}</button>`).join('')}</div>${rows()}`)}`}
function about(){return `<div class="pageheading"><h1>About</h1></div><div class="pagegrid">${panel('Hi, I’m Vishnu.','<p>I started in DevOps, primarily around cybersecurity. I’ve since moved into revenue operations, with experience in UI/UX and assisting marketing campaigns.</p><p>I’m working towards sales engineering: understanding a problem, explaining the technical pieces, and helping people find a workable solution.</p><h3>What I’m interested in</h3><ul><li>Security and infrastructure</li><li>How products communicate and sell</li><li>Interfaces that people can understand</li><li>Small, personal corners of the web</li></ul><p>This website is where my writing and experiments will gradually collect.</p>')}${panel('Elsewhere','<p>Contact details, professional links and a résumé will go here when supplied.</p><button class="button" data-notice>Contact / résumé</button>','yellow')}</div>`}
function guestbook(){return `<div class="pageheading"><h1>Guestbook</h1><p>Leave a note, if you like.</p></div><div class="pagegrid">${panel('The book','<p class="empty-note">No entries yet. Visitor notes will appear here.</p><div class="guest-entry"><div class="who">Example visitor <span class="sample">layout example</span></div><p>This is a sample of how a short guestbook entry will look.</p></div>')}${panel('Sign the guestbook',`<form id="guestform"><div class="formrow"><label for="guestname">Name</label><input id="guestname" maxlength="40" placeholder="Your name"></div><div class="formrow"><label for="guestmessage">Message</label><textarea id="guestmessage" maxlength="500" placeholder="Your note"></textarea></div><button class="button primary">Preview entry</button><p class="sample">Preview only. Nothing is saved or sent.</p></form><div id="entrypreview"></div>`,'yellow')}</div>`}
function maker(step='body'){let n=steps.findIndex(x=>x.toLowerCase()===step);if(n<0)n=0;let body='';const templates=['Goblin','Amphibian','Squirrel','Hopper','Pixel alien'];
if(n===0)body=`<div class="workstep"><h2>Choose a body template</h2><p>The template defines the joints. Your drawing supplies the character.</p><div class="body-picks">${templates.map((t,i)=>`<button class="body-pick ${i?'':'active'}" data-pick><span style="font-size:44px">${['♧','♙','♞','♟','▦'][i]}</span><h3>${t}</h3><p class="small-copy">${['Two legs, long arms','Upright, two arms','Upright body, large tail','A body and springy legs','A separate pixel rig'][i]}</p></button>`).join('')}</div><p class="sample">Template silhouettes and rigs will be refined with you before implementation.</p></div>`;
if(n===1)body=`<div class="creatorgrid">${panel('Your creature',`<div class="startchoices"><button class="button primary" data-example>Use example</button><button class="button" data-blank>Start blank</button></div><h3>Body parts</h3><div class="layerlist">${['Head','Body','Left arm','Right arm','Left leg','Right leg'].map((x,i)=>`<button class="${i?'':'selected'}" data-layer>◉ &nbsp; ${x}</button>`).join('')}</div><p class="small-copy">Draw each part on its own layer. Guides help it fit the shared rig.</p>`)}<section class="panel"><div class="panelbody"><div class="toolstrip">${['Pencil','Brush','Eraser','Fill','Select','Undo'].map((x,i)=>`<button class="button ${i?'':'active'}" data-tool>${x}</button>`).join('')}</div><div class="paintbar"><div class="swatches">${['#111111','#ffffff','#99dd60','#157cf2','#7453a3','#d17e37','#e85f50'].map((c,i)=>`<button aria-label="Color ${c}" class="swatch ${i?'':'active'}" style="background:${c}" data-swatch></button>`).join('')}</div><label>Custom <input type="color" value="#99dd60"></label><label>Size <input type="range" min="1" max="20" value="4" aria-label="Brush size"></label></div><div class="drawingpaper"><span class="paper-tag">Example artwork · drawing disabled</span><img src="assets/goblin.png" alt="Goblin example drawing"><svg class="rig" viewBox="0 0 245 305" aria-label="Joint guides"><g class="skeleton" fill="none" stroke="#d88e20" stroke-width="2"><path d="M122 55V175L90 265M122 175L152 265M122 105L55 170M122 105L190 170"/></g><g fill="#ffc45a" stroke="#865918">${[[122,55],[122,105],[122,175],[90,265],[152,265],[55,170],[190,170]].map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="5"/>`).join('')}</g></svg></div><div class="paperoptions"><label><input type="checkbox" id="guides" checked> Show joint guides</label><span class="sample">Canvas preview</span></div></div></section>${panel('Preview','<div class="preview-creature"><img src="assets/goblin.png" alt="Goblin pose preview"></div><div class="motionstrip"><button class="button active" data-motion>Rest pose</button><button class="button" data-motion>Idle</button><button class="button" data-motion>Walk</button></div><p class="small-copy">Animations will be reviewed separately. This is a still pose.</p>','green')}</div>`;
if(n===2)body=`<div class="workstep movement-layout"><div><h2>Fit the drawing to the rig</h2><p>Place shoulders, hips and hands. A shared skeleton will let very different drawings use the same movements.</p><h3>Animation set</h3><div class="motion-list">${['Idle','Walk','Sit','Carry','Offer / receive','Work','Celebrate','Disagree'].map((t,i)=>`<button class="button ${i?'':'active'}" data-motion>${t}</button>`).join(' ')}</div><p class="sample">Static animation selector. No animation is running.</p></div><div class="preview-creature" style="height:340px"><img style="height:330px" src="assets/goblin.png" alt="Goblin rest pose"></div></div>`;
if(n===3)body=`<div class="workstep"><h2>Personality</h2><p>Preferences, not skill points. Each trait should bring trade-offs.</p>${[['Openness','Familiar things','New experiences'],['Conscientiousness','Flexible','Structured'],['Extraversion','Solitude','Company'],['Agreeableness','Assertive','Accommodating'],['Neuroticism','Even-tempered','Sensitive']].map(([t,l,r])=>`<div class="trait"><strong>${t}</strong><div><input type="range" min="0" max="100" value="50" aria-label="${t}"><div class="traitends"><span>${l}</span><span>${r}</span></div></div></div>`).join('')}<p class="sample">These controls demonstrate the creation screen. They do not affect a simulation yet.</p></div>`;
if(n===4)body=`<div class="workstep releasegrid"><img src="assets/goblin.png" alt="Example creature"><div><h2>Ready to move in?</h2><div class="formrow"><label for="creaturename">Creature name</label><input id="creaturename" placeholder="Name your creature" maxlength="30"></div><div class="formrow"><label for="creaturebio">A short introduction</label><textarea id="creaturebio" placeholder="Optional"></textarea></div><p>Eventually, your creature will join the village. The homepage shows five residents at a time.</p><button class="button primary" data-notice>Sign in &amp; release</button><p class="sample">Accounts and release are not connected.</p></div></div>`;
return `<div class="pageheading creator-heading"><div><a href="#/play">← Play</a><h1>Make a creature</h1></div><span class="badge">Layout preview</span></div><nav class="stepper" aria-label="Creation steps">${steps.map((x,i)=>`<a class="button ${i===n?'primary':''}" ${i===n?'aria-current="step"':''} href="#/maker/${x.toLowerCase()}">${i+1}. ${x}</a>`).join('')}</nav>${body}<div class="creator-actions">${n?btn('← '+steps[n-1],'maker/'+steps[n-1].toLowerCase()):btn('← Play','play')}${n<4?btn('Next: '+steps[n+1]+' →','maker/'+steps[n+1].toLowerCase(),true):btn('Look around the village →','village',true)}</div>${note}`}
function village(tab='map'){const tabs=`<div class="village-tabs">${[['map','Village'],['creature','My creature'],['activity','Activity'],['economy','Economy']].map(([k,t])=>btn(t,'village/'+k,k===tab)).join(' ')}</div>`;let body='';if(tab==='economy')body=panel('Shared resources',`<p class="sample">Illustrative economy screen. These numbers are examples.</p><div class="economygrid">${[['Food','128'],['Timber','36'],['Shared seats','12']].map(([x,n])=>`<div class="stat"><span>${x}</span><strong>${n}</strong></div>`).join('')}</div><h3>Commitments</h3><table class="ledger"><thead><tr><th>From</th><th>To</th><th>Agreement</th><th>Status</th></tr></thead><tbody><tr><td>Moss</td><td>Pip</td><td>Repair a stool for 3 food</td><td>Example</td></tr><tr><td>Community</td><td>Garden</td><td>Two turns tending berries</td><td>Example</td></tr></tbody></table><p>Ownership, shared access and debts will be visible here. The rules are still to be designed.</p>`);else if(tab==='activity')body=panel('Village log','<p class="sample">Example events · not a live feed</p><ul class="activitylist"><li>Moss offered Pip some berries.</li><li>Two residents shared a seat by the pond.</li><li>A stool needs repairing at the workshop.</li></ul>');else if(tab==='creature')body=panel('Your creature','<div class="aboutintro"><div><h3>No creature yet</h3><p>Once the game is connected, this page will show their needs, relationships and commitments.</p>'+btn('Explore the creator →','maker/body',true)+'</div><img src="assets/goblin.png" alt="Example goblin"></div>');else body=`<div class="village-layout"><section class="panel" id="mapPanel"><div class="maptools"><strong id="placeTitle">The village</strong><span class="spacer"></span><button class="button small" id="zoomout" aria-label="Zoom out">−</button><span id="zoomvalue">100%</span><button class="button small" id="zoomin" aria-label="Zoom in">+</button><button class="button small" id="expand">Expand map ↗</button></div><div class="mapviewport" id="mapview" tabindex="0" aria-label="Village map. Scroll or drag to explore."><div class="world" style="height:700px"><img src="assets/village.png" alt="Large village panorama with a pond, berry garden, workshop and mushroom homes" draggable="false">${[['Pond',12,65],['Garden',45,65],['Workshop',63,46],['Homes',84,44]].map(([t,x,y])=>`<button class="maplabel" style="left:${x}%;top:${y}%" data-place="${t}">${t}</button>`).join('')}</div></div><div class="mapcaption">Static world preview · drag or scroll to explore · more land can be added.</div></section>${panel('Resident preview','<div class="inspector-top"><img src="assets/goblin.png" alt="Moss the goblin"><div><h3>Moss</h3><p>By the garden</p><span class="sample">Example resident</span></div></div><p class="why">Gathering berries with a friend.</p><h3>Needs</h3><div class="needs">'+[['Hunger',28],['Fatigue',45],['Boredom',18],['Loneliness',22]].map(([t,v])=>`<div class="needrow"><span>${t}</span><div class="bar"><i style="width:${v}%"></i></div></div>`).join('')+'</div><details><summary>Relationships</summary><p>Pip — familiar friend<br>Fern — new acquaintance</p></details><details><summary>Possessions &amp; promises</summary><p>4 food, a shared stool.<br>Example: help repair the bench.</p></details><p class="sample">All resident data is illustrative.</p>','green')}</div><div class="village-bottom">${panel('Around the village','<p class="sample">Example activity</p><ul class="activitylist"><li>Moss and Pip are at the garden.</li><li>The workshop has a stool to repair.</li><li>A quiet spot by the pond is free.</li></ul>')}${panel('Find a place',`<div class="my-controls">${['Pond','Garden','Workshop','Homes'].map(x=>`<button class="button" data-jump="${x}">${x}</button>`).join(' ')}</div><p class="small-copy">The homepage hill is one meeting place within this larger world.</p>`,'yellow')}</div>`;return `<div class="pageheading"><h1>The village</h1><p>A little world alongside the rest of the website.</p></div>${tabs}${body}${note}`}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
function render(){document.body.style.overflow='';const parts=location.hash.replace(/^#\/?/,'').split('/');const route=parts[0];document.querySelector('.mainnav').innerHTML=nav.map(([r,i,t])=>`<a href="#/${r}" ${(route===r||(r==='play'&&['maker','village'].includes(route)))?'aria-current="page"':''}><span aria-hidden="true">${i}</span> ${t}</a>`).join('');main.innerHTML=route==='writing'?writing(parts[1]):route==='about'?about():route==='guestbook'?guestbook():route==='maker'?maker(parts[1]):route==='village'?village(parts[1]):route==='play'?`<div class="pageheading"><h1>Play</h1><p>A small detour.</p><a class="button primary" href="lab.html">Society lab: behaviour, contracts & experiments →</a></div>${panel('The creature village',playcards(),'green')}${note}${hill()}`:home();document.title='vishnu.is — '+(nav.find(x=>x[0]===route)?.[2]|| (route==='maker'?'Make a creature':route==='village'?'The village':'Home'));window.scrollTo(0,0);bind()}
function select(el,selector,cls='active'){el.parentElement.querySelectorAll(selector).forEach(x=>x.classList.remove(cls));el.classList.add(cls)}
function bind(){document.querySelectorAll('[data-notice]').forEach(x=>x.onclick=()=>document.querySelector('#notice').showModal());document.querySelectorAll('[data-pick]').forEach(x=>x.onclick=()=>select(x,'[data-pick]'));document.querySelectorAll('[data-tool],[data-swatch],[data-motion]').forEach(x=>x.onclick=()=>select(x,'button'));document.querySelectorAll('[data-layer]').forEach(x=>x.onclick=()=>select(x,'button','selected'));document.querySelector('[data-blank]')?.addEventListener('click',()=>document.querySelector('.drawingpaper').classList.add('blank'));document.querySelector('[data-example]')?.addEventListener('click',()=>document.querySelector('.drawingpaper').classList.remove('blank'));document.querySelector('#guides')?.addEventListener('change',e=>document.querySelector('.rig').hidden=!e.target.checked);document.querySelectorAll('[data-filter]').forEach(x=>x.onclick=()=>{select(x,'button');document.querySelectorAll('[data-category]').forEach(row=>row.hidden=x.dataset.filter!=='All'&&row.dataset.category!==x.dataset.filter)});document.querySelector('#guestform')?.addEventListener('submit',e=>{e.preventDefault();const p=document.querySelector('#entrypreview');p.replaceChildren();const title=document.createElement('h3');title.textContent='Local preview: '+(document.querySelector('#guestname').value||'Visitor');const message=document.createElement('p');message.textContent=document.querySelector('#guestmessage').value||'Write a note to preview it.';p.append(title,message)});const view=document.querySelector('#mapview');if(view){let zoom=1;const world=view.querySelector('.world');const resize=delta=>{const x=(view.scrollLeft+view.clientWidth/2)/world.offsetWidth,y=(view.scrollTop+view.clientHeight/2)/world.offsetHeight;zoom=Math.max(.5,Math.min(1.5,zoom+delta));world.style.width=2100*zoom+'px';world.style.height=700*zoom+'px';view.scrollLeft=x*world.offsetWidth-view.clientWidth/2;view.scrollTop=y*world.offsetHeight-view.clientHeight/2;document.querySelector('#zoomvalue').textContent=Math.round(zoom*100)+'%'};document.querySelector('#zoomout').onclick=()=>resize(-.25);document.querySelector('#zoomin').onclick=()=>resize(.25);const expand=document.querySelector('#expand');expand.onclick=()=>{const on=document.querySelector('#mapPanel').classList.toggle('expanded-map');expand.textContent=on?'Close expanded view ×':'Expand map ↗';expand.setAttribute('aria-expanded',on);document.body.style.overflow=on?'hidden':''};let drag;view.onpointerdown=e=>{if(e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY,left:view.scrollLeft,top:view.scrollTop};view.setPointerCapture(e.pointerId)};view.onpointermove=e=>{if(drag){view.scrollLeft=drag.left-e.clientX+drag.x;view.scrollTop=drag.top-e.clientY+drag.y}};view.onpointerup=view.onpointercancel=()=>drag=null;const jump=name=>{const target=[...world.querySelectorAll('[data-place]')].find(x=>x.dataset.place===name);view.scrollLeft=target.offsetLeft-view.clientWidth/2;view.scrollTop=target.offsetTop-view.clientHeight/2;world.querySelectorAll('button').forEach(x=>x.classList.toggle('chosen',x===target));document.querySelector('#placeTitle').textContent=name};document.querySelectorAll('[data-place],[data-jump]').forEach(x=>x.onclick=()=>jump(x.dataset.place||x.dataset.jump));view.scrollLeft=500;view.scrollTop=170}}
document.querySelector('#previewInfo').onclick=()=>document.querySelector('#notice').showModal();document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.expanded-map'))document.querySelector('#expand').click()});window.addEventListener('hashchange',render);render();

